1	// Every panel in the working dataset is named VESSEL_<prefix>_... and lives under
2	// references/<paper-slug>/figures/panels/. The px -> um scale is measured from the scale bar
3	// the figure prints and tabulated as SCALEBAR_PX in the extraction script, keyed by panel-name
4	// prefix (longest match wins) so one figure can calibrate rows that differ in zoom.
5	//
6	// A panel may instead carry its scale DIRECTLY, in UMPP_DIRECT, when the source image's own
7	// metadata states um/px and no bar is involved — stronger evidence than a measured bar.
8	//
9	// A panel whose scale genuinely cannot be measured — the figure draws no bar — is not a
10	// violation, but it must SAY so: an entry in UNCALIBRATED, carrying the reason. The point of
11	// this rule is that no panel is uncalibrated by accident.
12	const PANEL = /^references\/[^/]+\/figures\/panels\/VESSEL_(.+)\.png$/i;
13	const MEASURE = 'analysis/measure_vessels.py';
14	const TABLE = /SCALEBAR_PX\s*=\s*\{([\s\S]*?)\}/;
15	const DIRECT = /UMPP_DIRECT\s*=\s*\{([\s\S]*?)\n\}/;
16	const DECLARED = /UNCALIBRATED\s*=\s*\{([\s\S]*?)\n\}/;
17	
18	// The wang-2022 panels carry a channel suffix the calibration keys never include.
19	const stripSuffix = (s) => s.replace(/_gP-CD31_red$/, '');
20	
