1	// The extraction script is the single place the three locked metrics are
2	// computed and named; every downstream table, overlay banner and results
3	// markdown quotes those field names back.
4	const MEASURE = 'analysis/measure_vessels.py';
5	
6	// The professor's three asks, and the metric fields each one is locked to.
7	const LOCKED = [
8	  { ask: 'COUNT', meaning: 'branch segments (junction-to-junction / junction-to-tip)', fields: ['segments'] },
9	  { ask: 'CATEGORIZE', meaning: 'caliber - capillary vs penetrating artery by centerline diameter', fields: ['capillary', 'artery'] },
10	  { ask: 'MEASURE', meaning: 'total centerline length, as raw um and as density', fields: ['length_um', 'length_density'] },
11	];
12	
13	// Parse rather than grep: the metric names count only where they are built as
14	// keyword fields of a dict(...) construction, never where prose, a docstring or
15	// a print format string happens to mention them. `defaultdict(` is not a dict
16	// construction here, hence the non-word/non-dot lookbehind.
17	const DICT = /(?<![\w.])dict\s*\(/g;
18	const KWARG = /(?:^|[(,]\s*)([A-Za-z_]\w*)\s*=(?!=)/g;
19	
20	// The real metrics dict carries trailing `#` comments between its fields, which
21	// would otherwise sit between a field and the comma that anchors the next one.
22	// Blank them (keeping the newline) rather than the whole line, so line numbers
23	// still count. Quote-aware: a `#` inside a string literal is not a comment.
24	function stripComments(text) {
25	  return text.split('\n').map((line) => {
26	    let quote = null;
27	    for (let i = 0; i < line.length; i += 1) {
28	      const c = line[i];
29	      if (quote) {
30	        if (c === '\\') i += 1;
31	        else if (c === quote) quote = null;
32	      } else if (c === '"' || c === "'") quote = c;
33	      else if (c === '#') return line.slice(0, i);
34	    }
35	    return line;
36	  }).join('\n');
37	}
38	
39	// The fields of every dict(...) built in the script, with the line the first
40	// dict carrying a locked field starts on (where a reviewer should look).
41	function reportedFields(source) {
42	  const text = stripComments(source);
43	  const fields = new Set();
44	  let dicts = 0;
45	  let line = null;
46	  for (const m of text.matchAll(DICT)) {
47	    dicts += 1;
48	    let depth = 0;
49	    let end = m.index + m[0].length - 1;
50	    for (; end < text.length; end += 1) {
51	      if (text[end] === '(') depth += 1;
52	      else if (text[end] === ')' && (depth -= 1) === 0) break;
